"""Saved-outcome report for the preregistered AND(7,8) development study."""
import json,csv
from pathlib import Path
import numpy as np
from src.runtime import write_json
from ..run import digest,write_csv
from .run import C,RUN,OUT,ID,BASE


def read(path):return list(csv.DictReader(path.open()))


def produce():
    fixed=json.loads((RUN/'fixed_hypotheses.json').read_text());verification=json.loads((RUN/'model_verification.json').read_text());audit=json.loads((OUT/'development_audit.json').read_text());held=read(OUT/'heldout_group_metrics.csv');stress=read(OUT/'stress_group_metrics.csv');interventions=read(OUT/'heldout_interventions.csv');bootstrap=json.loads((OUT/'guided_vs_direct_bootstrap.json').read_text())
    rows=[r for r in held if r['control']=='False'];methods=['tc_guided_signed','direct_joint','direct_signed','direct_abs','historical_native']
    lines=['# Stage 3: Does transcoder guidance help discover the original AND(7,8) computation?','','## Scope and fixed protocol','','This study concerns only AND(7,8), semantic output g4. No teacher/transcoder training or weight edits occurred. Frozen teacher:12→256→12, seed3105; primary transcoder:12→1024→12, lambda1e-4, previously validation selected. Both were loaded in eval mode, parameters frozen, and prior validation predictions reproduced within atol2e-6/rtol2e-5.',f"\nTeacher SHA-256 `{verification['teacher_sha256']}`; transcoder SHA-256 `{verification['transcoder_sha256']}`. Original P/Q, dataset and manifest hashes are recorded in model_verification.json. Prior V1/V2 artifacts remain unchanged.",'','## New development contexts and leakage safeguards','',f"Discovery: {audit['discovery']['n_contexts']} contexts; held-out development: {audit['heldout']['n_contexts']}; OOD-density stress: {audit['stress']['n_contexts']}. Each is a complete four-corner table. Supported contexts have3/4 active background bits, making corner densities3..6. Backgrounds are sampled via the existing versioned generator, cleared at a7/a8 and deduplicated, then split by an independent deterministic seed without model outcomes. Contexts and all corner inputs are disjoint across these development partitions. Historical-test-overlap contexts and the prior AND(7,8) context bank are excluded.",'','The complete context/corner identity manifest records original train/validation overlap; these are held out from hypothesis discovery, not necessarily from original model training. This is development evidence, not final confirmation. The reserved final population file was neither opened nor evaluated. Because its identities remain unknown here, accidental input overlap cannot be excluded; future independent final confirmation must audit/exclude the published development keys. No claim of disjointness from that reserved file is made.','',f"Discovery input overlap counts: `{audit['discovery']['corner_overlap_counts']}`. Held-out overlap: `{audit['heldout']['corner_overlap_counts']}`. Seeds, proposal/acceptance counts and density/distractor support are in development_audit.json.",'','## Fair discovery comparison','','All methods preserve original readout coefficients and ReLU nonlinearities, with subset coefficients fixed at1; no readout weights are refitted. Output-effect fidelity compares corner-relative g4 responses y(a)−y(00), while absolute g4 approximation adds one discovery-fitted constant intercept per output. The intercept does not affect finite interactions. Useful compact fidelity was declared before scoring held-out outcomes: pair-response RMSE≤0.05 and interaction MAE≤0.05. Budgets1/3/5/10/20 are all reported, not selected after outcomes.','','- **TC-guided signed:** start with features173/266, expand their fixed group using discovery corner/interaction profiles, then select native groups to reproduce this proxy’s net and opposing signed-write channels across contexts. No one-to-one feature/neuron matching or cosine-only selection.','- **Direct joint (primary baseline):** signed forward selection plus up to8 one-swap passes to minimize equally normalized pair-response and interaction MSE against the actual teacher, not an arbitrary top-k ranking. Negative witnesses can improve the objective.','- **Direct signed:** same strong search with native positive/negative output-write channels alongside the net response.','- **Direct absolute:** conventional mean absolute interaction ranking, reported as a weaker reference.','- **Controls:**16 uniform random groups per budget; up to16 contribution-matched alternatives per selected group. Matching uses discovery absolute interaction mass, pair-response RMS and readout-sign counts. Strong-neuron matching may require overlap with the candidate; overlaps and matching quality are reported, and distinct sets are required. Poorly matched alternatives are flagged rather than called valid matches.','','The complete fixed sets, discovery-only intercepts, clamp values, threshold hypotheses and predicted intervention means were written and hashed before any held-out/stress forward pass. Predictions cannot be revised based on the results below. The historical trio224/192/30 is explicitly a reference, not a presumed mechanism.','',f"TC discovery group selected from budgets2/3/5/10/20: k={fixed['selection']['selected_tc_budget']}, units={fixed['selection']['selected_tc_units']}. Its sufficiency versus the full transcoder and teacher is tested separately from original-neuron sufficiency.",'','## Held-out original-neuron group sufficiency','','| Method | k | Neurons | g4 absolute MSE | Pair-response RMSE | Interaction MAE | Positive sum | Negative sum | Cancellation |','|---|---:|---|---:|---:|---:|---:|---:|---:|']
    lookup={g['name']:g for g in fixed['groups']}
    for r in rows:lines.append('| '+r['method']+' | '+r['k']+' | '+str(lookup[r['name']]['neurons'])+' | '+' | '.join(f'{float(r[k]):.6g}' for k in ('absolute_g4_mse','pair_response_g4_rmse','interaction_g4_mae','mean_positive_interaction_sum','mean_negative_interaction_sum','mean_cancellation'))+' |')
    lines+=['','### Smallest useful budget in the preregistered grid','','| Method | Smallest held-out budget meeting both thresholds |','|---|---:|']
    for method in methods:
        passing=[int(r['k']) for r in rows if r['method']==method and float(r['pair_response_g4_rmse'])<=.05 and float(r['interaction_g4_mae'])<=.05]
        lines.append('| '+method+' | '+(str(min(passing)) if passing else 'none')+' |')
    lines+=['','These smallest-budget descriptions summarize the fixed grid; they are not new fitted hypotheses selected on held-out outcomes.','','## Primary paired comparison: guidance versus strong direct baseline','','Positive differences mean the guided interaction approximation is worse. Confidence intervals resample development contexts with a fixed seed; correlated feature combinations and reused model training inputs limit broader inference.','','| k | Guided minus direct interaction MAE | Paired context bootstrap95% |','|---:|---:|---|']
    for r in bootstrap:lines.append(f"| {r['k']} | {r['guided_minus_direct_interaction_mae']:.6g} | {r['paired_context_bootstrap95']} |")
    lines+=['','## Original-neuron interventions and predictive tests','','Actual frozen-model hidden activations are intervened upon, followed by the original W2/b2 readout. **Zero ablation** sets selected activations to0. **Clamping** replaces them with each neuron’s mean discovery00 activation, fixed before held-out evaluation. All other original activations and every model weight remain unchanged. Constant clamping and zeroing remove the same selected pairwise interaction; their absolute output/collateral effects differ. They are not independent confirmations of interaction removal.','','The exact signed sum of realized held-out neuron contributions predicts zero-ablation effects by identity. We verify that identity but do not treat it as discovery. Nontrivial predictions are: (1) discovery-mean corner effects; (2) original pair coefficients with discovery-mean background offsets (context-invariant gate hypothesis); (3) original pair coefficients plus two discovery-selected variable context coefficients per neuron, replacing omitted reads by their discovery means. These compact threshold formulas are derived without training another network. Their held-out effect residuals, including collateral outputs, test contextual generalization.','','| Method | k | Intervention | Measured g4 interaction change | Invariant-gate predicted-effect RMSE | Context2-gate effect RMSE | Context2 interaction-effect MAE | Mean absolute collateral effect |','|---|---:|---|---:|---:|---:|---:|---:|']
    names={r['name'] for r in rows}
    for r in interventions:
        if r['name'] not in names:continue
        lines.append('| '+r['method']+' | '+r['k']+' | '+r['intervention']+' | '+' | '.join(f'{float(r[k]):.6g}' for k in ('g4_mean_interaction_change','invariant_gate_g4_effect_rmse','context2_gate_g4_effect_rmse','context2_gate_g4_interaction_effect_mae','mean_abs_collateral_effect'))+' |')
    lines+=['','Full per-output mean effects and interaction changes (g0..g8), class flips, predictor errors and actual candidate intervention arrays are saved. g8 contains the AND clause, so a g8 effect can reflect shared computation rather than an intrinsically undesirable error. Other-output collateral responses must be assessed individually.','','## Control distributions','','| Candidate | Qualified matched groups | Total matched groups | Mean neuron overlap (matched) | Candidate interaction MAE | Matched MAE median | Uniform-random MAE median |','|---|---:|---:|---:|---:|---:|---:|']
    for r in rows:
        if r['method']=='historical_native':continue
        matched=[v for v in held if v['matched_to']==r['name']];qualified=[v for v in matched if v['matching_qualified']=='True'];random=[v for v in held if v['method']=='random' and v['k']==r['k']]
        lines.append('| '+r['name']+' | '+str(len(qualified))+' | '+str(len(matched))+' | '+(f"{np.mean([float(v['matched_overlap']) for v in matched]):.3f}" if matched else '—')+' | '+f"{float(r['interaction_g4_mae']):.6g}"+' | '+(f"{np.median([float(v['interaction_g4_mae']) for v in qualified]):.6g}" if qualified else 'unmatched')+' | '+f"{np.median([float(v['interaction_g4_mae']) for v in random]):.6g}"+' |')
    lines+=['','## Candidate transcoder and native thresholds','','For every original neuron, the audit retains all20 C1 coefficients, original bias, all9 D2_eff writes, gate-pattern counts, background-offset quantiles, all four corner activation means and signed interaction statistics. Features173/266 and the augmented TC group have the same analysis with K/A. A context offset η=b+sum_{i not7,8} coefficient_i*a_i gives preactivations [η,η+w8,η+w7,η+w7+w8]. An11-only gate requires the first three≤0 and the last>0. Both positive and negative output writes can share this gate. Strong attribution is not itself an AND-detector label.','','| Model / unit | Held-out 11-only gate fraction | Mean interaction | Interaction SD | Mean corner activations |','|---|---:|---:|---:|---|']
    thresholds=json.loads((OUT/'heldout_thresholds/units.json').read_text())
    selected=set([224,192,30])|{u for g in fixed['groups'] if g['method'] in ('tc_guided_signed','direct_joint') and g['k']==3 for u in g['neurons']}
    for r in thresholds:
        if (r['model']=='native' and r['unit'] in selected) or (r['model']=='transcoder' and r['unit'] in [173,266]):lines.append(f"| {r['model']} / {r['unit']} | {r['11_only_gate_fraction']:.4f} | {r['mean_interaction']:.6g} | {r['interaction_sd']:.6g} | {r['mean_corner_activation']} |")
    lines+=['','## OOD-density stress: same fixed hypotheses','','| Method | k | Pair-response RMSE | Interaction MAE |','|---|---:|---:|---:|']
    for r in stress:
        if r['control']=='False':lines.append('| '+r['method']+' | '+r['k']+' | '+f"{float(r['pair_response_g4_rmse']):.6g} | {float(r['interaction_g4_mae']):.6g} |")
    lines+=['','## Scientific interpretation','','ASSESSMENT_PENDING','','## Artifacts and execution','','[Compact-group fidelity](group_fidelity.png) · [Threshold prediction errors](intervention_prediction.png) · [Gate conditions](gate_conditions.png)','','- development_contexts.npz, development_manifest.json, development_audit.json: deterministic population, exact split/corner identities and original-data overlap.','- discovery_exact.npz, heldout_exact.npz, stress_exact.npz: complete signed native/TC neuron contributions, original latent activations and direct outputs.','- native_coordinates.npz / transcoder_coordinates.npz: every known input/output coefficient and bias.','- *_thresholds/units.json and tc_anchor_deviations.json: all original neurons, selected TC units and explicit gate failures.','- heldout/stress_group_metrics.csv, *_interventions.csv and *_candidate_effects.npz: all group/control results, full candidate effects and frozen compact predictions.','- fixed_hypotheses.json, fixed_gate_parameters.npz and discovery_frozen.json under ../../runs/'+ID+'/: immutable predictions and the timestamp-order/hashes proving selection preceded held-out forward evaluation.','- Config/source snapshots, model verification, protection hashes, execution status and logs are preserved. No reserved final population access or model training.']
    (OUT/'report.md').write_text('\n'.join(lines)+'\n');plots(rows,interventions,thresholds)
    write_json(RUN/'report_generation.json',{'report_sha256':digest(OUT/'report.md'),'report_source_sha256':digest(__file__)})


def plots(rows,interventions,thresholds):
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(12,4))
    for method in ['tc_guided_signed','direct_joint','direct_signed','direct_abs']:
        rr=sorted([r for r in rows if r['method']==method],key=lambda r:int(r['k']))
        for ax,key in zip(axes,['pair_response_g4_rmse','interaction_g4_mae']):ax.plot([int(r['k']) for r in rr],[float(r[key]) for r in rr],'o-',label=method)
    for ax,title in zip(axes,['Held-out pair-response RMSE','Held-out interaction MAE']):ax.axhline(.05,color='black',ls='--');ax.set_title(title);ax.set_xlabel('Original neuron budget');ax.legend(fontsize=7)
    fig.tight_layout();fig.savefig(OUT/'group_fidelity.png',dpi=170);plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(12,4))
    for method in ['tc_guided_signed','direct_joint','direct_signed','direct_abs']:
        rr=sorted([r for r in interventions if r['method']==method and r['intervention']=='zero'],key=lambda r:int(r['k']))
        for ax,key in zip(axes,['invariant_gate_g4_effect_rmse','context2_gate_g4_effect_rmse']):ax.plot([int(r['k']) for r in rr],[float(r[key]) for r in rr],'o-',label=method)
    for ax,title in zip(axes,['Invariant-gate intervention prediction','Two-context-read gate prediction']):ax.set_title(title);ax.set_xlabel('Original neuron budget');ax.set_ylabel('Held-out g4 effect RMSE');ax.legend(fontsize=7)
    fig.tight_layout();fig.savefig(OUT/'intervention_prediction.png',dpi=170);plt.close(fig)
    fig,ax=plt.subplots(figsize=(9,4));rr=[v for v in thresholds if (v['model']=='native' and v['unit'] in [224,192,30]) or (v['model']=='transcoder' and v['unit'] in [173,266])]
    for r in rr:ax.plot(range(4),r['mean_corner_activation'],'o-',label=f"{r['model']} {r['unit']}")
    ax.set_xticks(range(4),['00','01','10','11']);ax.set_title('Held-out mean ReLU responses; context variation retained in data');ax.legend();fig.tight_layout();fig.savefig(OUT/'gate_conditions.png',dpi=170);plt.close(fig)
